import json,re,sys,collections
sys.path.insert(0,'/home/claude/vote-informed/scripts/data/tenure/cities-a/northmiami-src')
import nm_party
R=json.load(open('items.json'))
SKIP=re.compile(r'PROCLAIM|RECOGNIZ|HONORING|CO-?DESIGNAT|DESIGNATING .{0,80}(STREET|AVENUE|PLACE|WAY|DRIVE|DAY|MONTH|WEEK)|RENAMING|URGING|SUPPORTING|OPPOSING|MILLAGE|TENTATIVE BUDGET|FINAL BUDGET|OPERATING BUDGET|BUDGET AMENDMENT|AMENDING THE (FISCAL|BUDGET)|ELECTION|BALLOT|CHARTER|MUTUAL AID|INTERLOCAL|APPOINT|EMPLOYMENT AGREEMENT|CITY MANAGER.{0,40}(SEARCH|RECRUIT)|SIGNATOR|AMENDING (CHAPTER|SECTION|ARTICLE|THE CODE|THE CITY.S CODE)|PAY PLAN|COMPENSATION INCREASE|HOLIDAY|COLOR PALETTE|FLAGS|WORKSHOP|DIRECTING THE (INTERIM )?CITY MANAGER TO (REVIEW|CONDUCT|PREPARE|CREATE|DEVELOP|STUDY|EXPLORE|RESEARCH|PRESENT|UPDATE|IDENTIFY|PROVIDE A)|STATE OF FLORIDA DEPARTMENT|FLORIDA DEPARTMENT OF|MIAMI-DADE COUNTY (TRANSPORTATION|DEPARTMENT|PUBLIC|WATER|BOARD)|GRANT APPLICATION|APPLY FOR|ACCEPT(ING)? (A |THE )?(GRANT|FUNDING|AWARD)|ACCEPTING .{0,60}GRANT|LEGISLATIVE PRIORIT|FINANCIAL EMERGENCY|STATE OF EMERGENCY|DECLARING|RECOVERY PLAN|FINANCIAL RECOVERY|AUDIT COMMITTEE|COLLECTIVE BARGAINING|BENEVOLENT|AFSCME|UNION|TEAMSTERS|SURPLUS',re.I)
KEEP=re.compile(r'AGREEMENT|CONTRACT|PIGGYBACK|PURCHASE|AWARD|BID|RFP|RFQ|ITB|SETTLE|LEASE|SALE|CONVEY|SITE PLAN|PLAT|VARIANCE|REZON|ZONING|LAND USE|SPECIAL EXCEPTION|DEVELOPMENT AGREEMENT|CHANGE ORDER|WORK ORDER|RENEW|EXTEND|SPONSOR|DONAT|FUNDING TO|GRANT TO|ALLOCAT|WAIV|LICENSE|EASEMENT|VENDOR|SERVICES|LLC|INC\b|CORP',re.I)
out=[]
for i,r in enumerate(R):
  t=r['title']
  core=re.sub(r'^.*?FLORIDA,?\s*','',t,count=1)
  if SKIP.search(core[:400]) and not re.search(r'SETTLE|SITE PLAN|PLAT|VARIANCE|REZON|SPECIAL EXCEPTION|DEVELOPMENT AGREEMENT|PIGGYBACK',core[:300]): continue
  if not KEEP.search(core): continue
  ps=nm_party.parties(core.upper())
  out.append({'i':i,'date':r['date'],'type':r['type'],'sec':r['sec'],'num':r['num'],'orig':r['orig'],'parties':ps,'core':core[:600]})
json.dump(out,open('cand.json','w'),ensure_ascii=False,indent=0)
print(len(out),collections.Counter(o['date'][:4] for o in out))
with open('cand.txt','w') as f:
  for o in out: f.write('%d|%s|%s|%s.%s|%s| %s\n'%(o['i'],o['date'],o['type'][:3],o['sec'],o['num'] or '',' ; '.join(o['parties']),o['core'][:260]))
